/**
 * UUIDs: version 7 for new IDs and the lowercase canonical form accepted as a public ID.
 *
 * @module
 */
import { v7 } from 'uuid'

/** A lowercase canonical UUID of version 7 with the RFC 9562 variant. */
export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/

/**
 * A new canonical UUID v7, generated by the uuid package with its secure random source.
 *
 * @param now - Unix epoch milliseconds; IDs made later sort after it.
 */
export function uuidv7(now: number = Date.now()): string {
  return v7({ msecs: now })
}

/** Whether `value` is a lowercase canonical v7 UUID. */
export function isUuid(value: string): boolean {
  return UUID_PATTERN.test(value)
}
